"use client";

import type { ComponentProps, ReactNode } from "react";
import { Trash2Icon, LoaderIcon } from "lucide-react";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";
import { formatFileSize, truncateFileName } from "@dimah-s3/core";
import type { DeleteHooks } from "@dimah-s3/react";
import type { S3Api } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import { useDelete } from "@dimah-s3/react";
import { resolveStatusSlot, type StatusSlot } from "@/registry/dimah-s3-ui/lib/status-slot";
import { Button } from "@/registry/dimah-s3-ui/components/ui/button";
import { StatusAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/status-attachment";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/registry/dimah-s3-ui/components/ui/alert-dialog";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/registry/dimah-s3-ui/components/ui/tooltip";
import { useDeleteToast } from "@/registry/dimah-s3-ui/hooks/use-delete-toast";

/** Keep LTR file names and sizes readable inside RTL confirmation copy. */
function isolateLtr(value: string): string {
  return `\u2066${value}\u2069`;
}

/** Props for {@link DeleteButton}. */
export type DeleteButtonProps = DeleteHooks & {
  /** S3Api. Optional when an `<S3Provider>` is present in the tree. */
  api?: S3Api;
  /** S3 object key to delete. */
  objectKey: string;
  /** Display file name in the confirmation dialog. */
  fileName?: string;
  /** Display file size in the confirmation dialog. */
  fileSize?: number;
  /** Target bucket (overrides server default). */
  bucket?: string;
  /** Button label. */
  label?: string;
  /** Custom button content. Replaces default icon + label. */
  children?: ReactNode;
  className?: string;
  disabled?: boolean;
  tooltipText?: string;
  /** Show a toast during delete. @default true */
  toast?: boolean;
  /**
   * Inline status control.
   * - `true` (default): render below the button
   * - `false`: hide status
   * - `(node) => ReactNode`: wrap or relocate the status node
   */
  status?: StatusSlot;
  confirmTitle?: string;
  confirmDescription?: string;
  /** Button variant. @default "destructive" */
  variant?: ComponentProps<typeof Button>["variant"];
  /** Button size. @default "default" */
  size?: ComponentProps<typeof Button>["size"];
  /** Extra classes on the trigger button element. */
  buttonClassName?: string;
};

export function DeleteButton({
  api,
  objectKey,
  fileName,
  fileSize,
  bucket,
  label,
  children,
  className,
  disabled,
  tooltipText,
  toast: enableToast = true,
  status: statusSlot = true,
  confirmTitle,
  confirmDescription,
  variant = "destructive",
  size = "default",
  buttonClassName,
  beforeDelete,
  onDeleteStart,
  onSuccess,
  onError,
}: DeleteButtonProps) {
  const t = useTranslations();
  const displayName = fileName ?? objectKey.split("/").pop() ?? objectKey;
  const toastHandlers = useDeleteToast({
    enabled: enableToast,
    displayName,
  });

  const del = useDelete({
    api,
    bucket,
    beforeDelete,
    onDeleteStart,
    onSuccess: (key) => {
      toastHandlers.onSuccess(key);
      onSuccess?.(key);
    },
    onError: (key, error, phase) => {
      toastHandlers.onError(key, error);
      onError?.(key, error, phase);
    },
  });

  const isDeleting = del.phase === "deleting";
  const isDisabled = disabled || isDeleting;

  const buttonContent = children ?? (
    <>
      {isDeleting ? (
        <LoaderIcon className="animate-spin" data-icon="inline-start" />
      ) : (
        <Trash2Icon data-icon="inline-start" />
      )}
      {label ?? t("Delete", { note: "button" })}
    </>
  );

  const fileLabel =
    fileSize != null
      ? `${truncateFileName(displayName)} (${formatFileSize(fileSize)})`
      : truncateFileName(displayName);

  const description =
    confirmDescription ??
    t(
      'Are you sure you want to delete "{name}"? This action cannot be undone.',
      {
        note: "dialog description",
        variables: { name: isolateLtr(fileLabel) },
      },
    );

  const statusNode =
    del.phase === "success" ? (
      <StatusAttachment
        state="done"
        title={t('"{name}" deleted', {
          note: "status",
          variables: { name: truncateFileName(displayName) },
        })}
      />
    ) : del.phase === "error" ? (
      <StatusAttachment
        state="error"
        title={t("Delete failed", { note: "status" })}
        description={del.error ?? undefined}
      />
    ) : null;

  return (
    <div className={cn("inline-flex flex-col gap-2", className)}>
      <div className="inline-flex items-center gap-2">
        <AlertDialog
          open={del.phase === "confirming"}
          onOpenChange={(open) => {
            if (!open) del.cancelDelete();
          }}
        >
          <Tooltip>
            <TooltipTrigger
              render={
                <AlertDialogTrigger
                  disabled={isDisabled}
                  onClick={() => del.requestDelete(objectKey)}
                  render={
                    <Button
                      variant={variant}
                      size={size}
                      className={buttonClassName}
                      disabled={isDisabled}
                    />
                  }
                />
              }
            >
              {buttonContent}
            </TooltipTrigger>
            <TooltipContent>
              {tooltipText ?? t("Delete file", { note: "tooltip" })}
            </TooltipContent>
          </Tooltip>

          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogMedia>
                <Trash2Icon />
              </AlertDialogMedia>
              <AlertDialogTitle>
                {confirmTitle ?? t("Delete file?", { note: "dialog title" })}
              </AlertDialogTitle>
              <AlertDialogDescription
                dir="auto"
                className="[overflow-wrap:anywhere]"
              >
                {description}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>
                {t("Cancel", { note: "dialog button" })}
              </AlertDialogCancel>
              <AlertDialogAction
                variant="destructive"
                onClick={() => del.confirmDelete()}
              >
                {t("Delete", { note: "dialog confirm" })}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>

      {resolveStatusSlot(statusSlot, statusNode)}
    </div>
  );
}

"use client";

import { truncateFileName } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import { useFormatDimahError } from "@dimah-s3/react";

import { toast } from "@/components/ui/toast";

export type DeleteToastOptions = {
  enabled?: boolean;
  displayName: string;
};

export function useDeleteToast({
  enabled = true,
  displayName,
}: DeleteToastOptions) {
  const t = useTranslations();
  const formatDimahError = useFormatDimahError();

  const onSuccess = (_key: string) => {
    if (!enabled) return;
    toast.add({
      type: "success",
      title: t("File deleted", { note: "toast" }),
      description: <span dir="auto">{truncateFileName(displayName)}</span>,
    });
  };

  const onError = (_key: string, error: unknown) => {
    if (!enabled) return;
    toast.add({
      type: "error",
      title: t("Delete failed", { note: "toast" }),
      description: (
        <span dir="auto" className="block [overflow-wrap:anywhere]">
          {formatDimahError(error)}
        </span>
      ),
    });
  };

  return { onSuccess, onError };
}

"use client";

import type { ReactNode } from "react";
import {
  AlertCircleIcon,
  CheckCircleIcon,
  LoaderCircleIcon,
} from "lucide-react";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";
import {
  Attachment,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
} from "@/registry/dimah-s3-ui/components/ui/attachment";
import type { AttachmentState } from "@/registry/dimah-s3-ui/lib/attachment-state";

/** @deprecated Use {@link AttachmentState}. */
export type StatusAttachmentState = AttachmentState;

export type { AttachmentState };

export type StatusAttachmentProps = {
  state: AttachmentState;
  title?: ReactNode;
  description?: ReactNode;
  media?: ReactNode;
  actions?: ReactNode;
  className?: string;
};

/**
 * Minimal Attachment shell for operation feedback (upload/download/delete).
 * Relies on Attachment `data-state` styles for error/done chrome.
 */
export function StatusAttachment({
  state,
  title,
  description,
  media,
  actions,
  className,
}: StatusAttachmentProps) {
  const defaultMedia =
    state === "error" ? (
      <AlertCircleIcon />
    ) : state === "done" ? (
      <CheckCircleIcon />
    ) : state === "processing" || state === "uploading" ? (
      <LoaderCircleIcon className="animate-spin" data-slot="spinner" />
    ) : null;

  return (
    <Attachment
      state={state}
      size="sm"
      orientation="horizontal"
      className={cn("w-full max-w-full", className)}
    >
      <AttachmentMedia>{media ?? defaultMedia}</AttachmentMedia>
      <AttachmentContent>
        {title != null ? (
          <AttachmentTitle className="max-w-[48ch]">{title}</AttachmentTitle>
        ) : null}
        {description != null ? (
          <AttachmentDescription
            className={
              state === "error"
                ? "overflow-visible whitespace-normal [overflow-wrap:anywhere]"
                : undefined
            }
          >
            {description}
          </AttachmentDescription>
        ) : null}
      </AttachmentContent>
      {actions ? <AttachmentActions>{actions}</AttachmentActions> : null}
    </Attachment>
  );
}

import type { ReactNode } from "react";

/**
 * Controls inline status rendering for wired UI components.
 *
 * - `true` (default): render the status node in the default slot
 * - `false`: hide status
 * - `(node) => ReactNode`: wrap or relocate the status node
 */
export type StatusSlot = boolean | ((node: ReactNode) => ReactNode);

/** Resolve a {@link StatusSlot} against a built status node. */
export function resolveStatusSlot(
  slot: StatusSlot = true,
  node: ReactNode,
): ReactNode {
  if (slot === false) return null;
  if (typeof slot === "function") return slot(node);
  return node;
}

import type { ComponentProps } from "react";
import { Attachment } from "@/registry/dimah-s3-ui/components/ui/attachment";

/**
 * Attachment `state` values — derived from the stock shadcn {@link Attachment}
 * prop (do not edit `components/ui/attachment.tsx`).
 */
export type AttachmentState = NonNullable<
  ComponentProps<typeof Attachment>["state"]
>;

import type { LucideIcon } from "lucide-react";
import {
  FileArchiveIcon,
  FileAudioIcon,
  FileCodeIcon,
  FileIcon,
  FileImageIcon,
  FileJsonIcon,
  FileSpreadsheetIcon,
  FileTextIcon,
  FileVideoIcon,
} from "lucide-react";

/**
 * Exactly 30 popular extensions → lucide file icons.
 * Do not grow past 30 — unknown types use {@link FileIcon} / MIME fallbacks.
 */
const EXT_ENTRIES = [
  // documents (4)
  ["pdf", FileTextIcon],
  ["doc", FileTextIcon],
  ["docx", FileTextIcon],
  ["txt", FileTextIcon],
  // sheets / slides (5)
  ["xls", FileSpreadsheetIcon],
  ["xlsx", FileSpreadsheetIcon],
  ["csv", FileSpreadsheetIcon],
  ["ppt", FileTextIcon],
  ["pptx", FileTextIcon],
  // archives (5)
  ["zip", FileArchiveIcon],
  ["rar", FileArchiveIcon],
  ["7z", FileArchiveIcon],
  ["tar", FileArchiveIcon],
  ["gz", FileArchiveIcon],
  // audio (3)
  ["mp3", FileAudioIcon],
  ["wav", FileAudioIcon],
  ["m4a", FileAudioIcon],
  // video (5)
  ["mp4", FileVideoIcon],
  ["mov", FileVideoIcon],
  ["webm", FileVideoIcon],
  ["mkv", FileVideoIcon],
  ["avi", FileVideoIcon],
  // images when no previewUrl (6)
  ["png", FileImageIcon],
  ["jpg", FileImageIcon],
  ["jpeg", FileImageIcon],
  ["gif", FileImageIcon],
  ["webp", FileImageIcon],
  ["svg", FileImageIcon],
  // data (2)
  ["json", FileJsonIcon],
  ["xml", FileCodeIcon],
] as const satisfies ReadonlyArray<readonly [string, LucideIcon]>;

/** Compile-time guard: keep the popular extension list at exactly 30. */
type AssertExactly30 = (typeof EXT_ENTRIES)["length"] extends 30
  ? true
  : never;
const _exactly30: AssertExactly30 = true;
void _exactly30;

const EXT_ICONS: Record<string, LucideIcon> = Object.fromEntries(EXT_ENTRIES);

function extensionOf(fileName: string): string {
  const base = fileName.split(/[/\\]/).pop() ?? fileName;
  const dot = base.lastIndexOf(".");
  if (dot <= 0 || dot === base.length - 1) return "";
  return base.slice(dot + 1).toLowerCase();
}

/**
 * Resolve a lucide file icon for a display name + optional MIME type.
 * Prefer the capped extension map; then MIME family; else generic file.
 */
export function resolveFileTypeIcon(
  fileName: string,
  fileType?: string | null,
): LucideIcon {
  const ext = extensionOf(fileName);
  const byExt = ext ? EXT_ICONS[ext] : undefined;
  if (byExt) return byExt;

  const mime = (fileType ?? "").toLowerCase();
  if (mime.startsWith("image/")) return FileImageIcon;
  if (mime.startsWith("audio/")) return FileAudioIcon;
  if (mime.startsWith("video/")) return FileVideoIcon;
  if (mime === "application/pdf") return FileTextIcon;
  if (
    mime === "application/zip" ||
    mime === "application/x-zip-compressed" ||
    mime === "application/x-7z-compressed" ||
    mime.includes("compressed") ||
    mime.includes("tar")
  ) {
    return FileArchiveIcon;
  }
  if (
    mime.includes("spreadsheet") ||
    mime.includes("excel") ||
    mime === "text/csv"
  ) {
    return FileSpreadsheetIcon;
  }
  if (mime.includes("json")) return FileJsonIcon;
  if (
    mime.startsWith("text/") ||
    mime.includes("msword") ||
    mime.includes("document") ||
    mime.includes("presentation") ||
    mime.includes("powerpoint")
  ) {
    return FileTextIcon;
  }

  return FileIcon;
}
